<script type="application/ld+json">
{"@context": "https://schema.org", "@type": "FAQPage", "mainEntity": [{"@type": "Question", "name": "Что такое сведения об операциях с целевыми средствами?", "acceptedAnswer": {"@type": "Answer", "text": "Это документ по форме 0501213, в котором исполнитель заранее раскрывает плановые поступления и расходы по контракту в разрезе кодов направления расходования. На их основе казначейство санкционирует платежи."}}, {"@type": "Question", "name": "Какой штраф за нарушение срока утверждения сведений об операциях?", "acceptedAnswer": {"@type": "Answer", "text": "С 1 января 2026 года за нарушение установленного срока утверждения сведений об операциях (не позднее 10-го рабочего дня) введена административная ответственность по статье 15.49 КоАП РФ. Штраф для должностных лиц — 10 000–50 000 ₽, для юридических лиц — 1–5% цены контракта, но не более 200 000 ₽. Срок утверждает заказчик, поэтому ответственность за его нарушение несёт он."}}, {"@type": "Question", "name": "По какой форме составляются сведения?", "acceptedAnswer": {"@type": "Answer", "text": "По форме с кодом по ОКУД 0501213, предусмотренной Порядком санкционирования операций (приказ Минфина России № 214н). Источники поступлений и направления расходования берутся из приложений к Порядку."}}, {"@type": "Question", "name": "Кто утверждает сведения об операциях?", "acceptedAnswer": {"@type": "Answer", "text": "Как правило, заказчик. Исполнитель может утвердить сведения самостоятельно, если заказчик направил разрешение на самостоятельное утверждение."}}, {"@type": "Question", "name": "В какой срок нужно утвердить сведения?", "acceptedAnswer": {"@type": "Answer", "text": "Заказчик утверждает сведения не позднее 10-го рабочего дня после их получения от участника. До утверждения платежи по заявленным кодам не проходят."}}, {"@type": "Question", "name": "Где формируются сведения?", "acceptedAnswer": {"@type": "Answer", "text": "В государственной системе «Электронный бюджет» с использованием электронной подписи. Там они хранятся, корректируются и связываются с операциями по счёту."}}, {"@type": "Question", "name": "Что будет, если кода нет в сведениях?", "acceptedAnswer": {"@type": "Answer", "text": "Платёж по этому коду не пройдёт санкционирование. Нужно дополнить сведения нужным направлением, переутвердить их и затем направить платёж."}}, {"@type": "Question", "name": "Можно ли изменить сведения после утверждения?", "acceptedAnswer": {"@type": "Answer", "text": "Да. При изменении плана расходов, появлении новых направлений или корректировке сумм сведения дополняют и переутверждают. Их поддержание в актуальном состоянии обязательно."}}, {"@type": "Question", "name": "Чем сведения связаны с отказами казначейства?", "acceptedAnswer": {"@type": "Answer", "text": "Неутверждённые, неактуальные сведения или отсутствие нужного кода — частая причина возврата платежей. Корректные сведения снимают значительную часть отказов."}}, {"@type": "Question", "name": "Кто поможет заполнить сведения и вести операции?", "acceptedAnswer": {"@type": "Answer", "text": "Сопровождение можно передать на аутсорсинг: эксперт формирует сведения, подбирает коды, проводит платежи и взаимодействует с ТОФК. Оставьте заявку — разберём вашу ситуацию."}}, {"@type": "Question", "name": "Что делать, если заказчик не утверждает Сведения в срок?", "acceptedAnswer": {"@type": "Answer", "text": "Пункт 9 Порядка № 214н даёт выход: если заказчик не утвердил Сведения, не оформил разрешение и не направил уведомление об отказе в установленный срок, исполнитель по государственному или муниципальному контракту утверждает Сведения самостоятельно — при условии исполнения обязательств в полном объёме либо при расторжении контракта с представлением дополнительного соглашения и документа о фактическом объёме. Для исполнителя по контракту внутри цепочки Сведения утверждает государственный заказчик по обращению участника."}}, {"@type": "Question", "name": "Можно ли утвердить Сведения самостоятельно при расширенном сопровождении?", "acceptedAnswer": {"@type": "Answer", "text": "Нет. По пункту 7 Порядка № 214н, если в отношении участника ведётся расширенное казначейское сопровождение с проведением экономического обоснования затрат, Сведения утверждает только заказчик. То же правило дублируется пунктом 10 Правил экономического обоснования затрат: полномочия по утверждению Сведений не подлежат передаче от заказчика."}}, {"@type": "Question", "name": "Почему остаток прошлого года виден на счёте, но платежи по нему не проходят?", "acceptedAnswer": {"@type": "Answer", "text": "Потому что до утверждения Сведений по пункту 6 Порядка № 214н такие средства учитываются на лицевом счёте без права расходования. Сначала нужно решение об использовании остатка или возвращённой дебиторской задолженности, принятое в порядке пункта 27 Положения, утверждённого постановлением Правительства РФ № 1496, затем Сведения, утверждённые получателем бюджетных средств. Только после этого казначейство отразит показатели на счёте."}}, {"@type": "Question", "name": "Что подать, если казначейское сопровождение ввели в уже действующий контракт?", "acceptedAnswer": {"@type": "Answer", "text": "Одновременно со Сведениями — информацию о суммах кассовых выплат, включая авансовые платежи, произведённых с даты заключения контракта до даты открытия лицевого счёта или раздела на нём. Рекомендуемый образец приведён в приложении № 15 к Порядку № 214н, к информации прилагаются копии документов, подтверждающих возникновение денежных обязательств. Требование введено приказом Минфина России от 25.12.2024 № 197н."}}, {"@type": "Question", "name": "Можно ли уменьшить сумму в Сведениях, если платежи уже прошли?", "acceptedAnswer": {"@type": "Answer", "text": "Только до уровня фактических операций. По пункту 12 Порядка суммы поступлений по коду источника, включая разрешённый остаток, должны быть больше или равны фактическим поступлениям по этому коду на дату изменения; планируемые выплаты по коду направления расходования — больше или равны уже произведённым расходам по нему. Опустить план ниже факта нельзя: казначейство не отразит такие показатели."}}, {"@type": "Question", "name": "Нужно ли переподавать Сведения в начале нового года?", "acceptedAnswer": {"@type": "Answer", "text": "Как правило, нет. Если Сведения утверждены на весь срок действия контракта либо содержат остатки планируемых поступлений и выплат на конец отчётного года, казначейство само отражает их показатели в «Электронном бюджете» не позднее первого рабочего дня текущего финансового года. Исключение — Сведения, утверждённые самим участником, если срок действия разрешения на утверждение истёк: тогда цикл утверждения нужно проходить заново."}}, {"@type": "Question", "name": "Может ли заказчик отозвать уже выданное разрешение?", "acceptedAnswer": {"@type": "Answer", "text": "Да, если это предусмотрено условиями контракта и есть нарушение его условий. По пункту 8 Порядка № 214н заказчик вправе на основании обращения, представленного в территориальный орган казначейства с одновременным уведомлением участника, отозвать разрешение на утверждение Сведений или утверждённые им Сведения. Норма введена приказом Минфина России от 25.12.2024 № 197н."}}]}
</script>
